static const uint32_t M = 2147483647L;   // 2^31-1
static const uint64_t A = 16807;         // bits 14,8,7,5,2,1,0
uint64_t product = seed_ * A;
seed_ = static_cast<uint32_t>((product >> 31) + (product & M));
if (seed_ > M) {
  seed_ -= M;
}
return seed_;

